function SettingsProvider({children}:{children:React.ReactNode}){const[st,setSt]=useState<SiteSettings>(SETTINGS_DEFAULTS);useEffect(()=>{let live=true;fetch(`${(import.meta.env.VITE_API_URL||"/api").replace(/\/$/,"")}/settings`).then(r=>r.ok?r.json():null).then((b:any)=>{if(!live||!b?.ok)return;const d=b.data as SiteSettings;setSt(d);const root=document.documentElement;root.style.setProperty("--color-orange",d.colorPrimary);root.style.setProperty("--color-plasma",d.colorAccent);root.style.setProperty("--color-neon",d.colorHighlight);}).catch(()=>{})},[]);return <SettingsCtx.Provider value={st}>{children}</SettingsCtx.Provider>}
