function renderArticleBody(body:string){const out:React.ReactNode[]=[];let last=0,i=0;const re=/```(\w*)\n?([\s\S]*?)```/g;let m:RegExpExecArray|null;while((m=re.exec(body))){if(m.index>last)out.push(...body.slice(last,m.index).split(/\n\s*\n/).filter(Boolean).map((p,k)=><p key={`p${i}-${k}`} className="text-lg leading-8">{p}</p>));out.push(<CodeBlock key={`c${i}`} language={m[1]||"ts"} code={m[2].replace(/\n$/,"")}/>);last=re.lastIndex;i++}if(last<body.length)out.push(...body.slice(last).split(/\n\s*\n/).filter(Boolean).map((p,k)=><p key={`t${i}-${k}`} className="text-lg leading-8">{p}</p>));return out}
function useRoute(){const[,set]=useState(0);useEffect(()=>{const f=()=>set(x=>x+1);addEventListener("hashchange",f);return()=>removeEventListener("hashchange",f)},[]);const[path,query]=location.hash.replace(/^#\/?/,"").split("?");const p=path.split("/");return{r:(p[0]||"home")as Route,id:p[1]||"",query:query||""}}
